messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Car Race</title>
<style>
  * { margin: 0; padding: 0; }
  body { overflow: hidden; background: #000; }
  canvas { display: block; }
</style>
</head>
<body>
<script type="importmap">
{
  "imports": {
    "three": "./three.module.js"
  }
}
</script>
<script type="module">
import * as THREE from './three.module.js';

// ── Setup ─────────────────────────────────────────────────────────────
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB);
scene.fog = new THREE.Fog(0x87CEEB, 120, 250);

const camera = new THREE.PerspectiveCamera(55, innerWidth / innerHeight, 0.1, 500);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

// ── Lights ───────────────────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0xffffff, 0.5));
const sun = new THREE.DirectionalLight(0xffffff, 1.2);
sun.position.set(20, 40, 30);
sun.castShadow = true;
scene.add(sun);

// ── Ground ────────────────────────────────────────────────────────────
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(400, 1000),
  new THREE.MeshLambertMaterial({ color: 0x3a7d3f })
);
ground.rotation.x = -Math.PI / 2;
ground.position.set(0, 0, -400);
scene.add(ground);

// Road
const road = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 1000),
  new THREE.MeshLambertMaterial({ color: 0x444444 })
);
road.rotation.x = -Math.PI / 2;
road.position.set(0, 0.01, -400);
scene.add(road);

// Road markings (dashed center line)
for (let z = 0; z < 1000; z += 6) {
  const mark = new THREE.Mesh(
    new THREE.PlaneGeometry(0.3, 3),
    new THREE.MeshLambertMaterial({ color: 0xffffff })
  );
  mark.rotation.x = -Math.PI / 2;
  mark.position.set(0, 0.02, -z);
  scene.add(mark);
}

// ── Finish Line ─────────────────────────────────────────────────────
const finishZ = -200;
const finishGeo = new THREE.PlaneGeometry(20, 1.5);
const finishMat = new THREE.MeshLambertMaterial({
  color: 0xff0000,
  side: THREE.DoubleSide
});
const finishLine = new THREE.Mesh(finishGeo, finishMat);
finishLine.rotation.x = -Math.PI / 2;
finishLine.position.set(0, 0.03, finishZ);
scene.add(finishLine);

// Finish line posts
for (const x of [-10, 10]) {
  const post = new THREE.Mesh(
    new THREE.BoxGeometry(0.5, 5, 0.5),
    new THREE.MeshLambertMaterial({ color: 0xffffff })
  );
  post.position.set(x, 2.5, finishZ);
  scene.add(post);
}
// Banner
const banner = new THREE.Mesh(
  new THREE.PlaneGeometry(20, 2),
  new THREE.MeshLambertMaterial({ color: 0xff3333, side: THREE.DoubleSide })
);
banner.position.set(0, 5.5, finishZ);
scene.add(banner);

// ── Car Builder ──────────────────────────────────────────────────────
function buildCar(color) {
  const car = new THREE.Group();

  // Body
  const body = new THREE.Mesh(
    new THREE.BoxGeometry(2.5, 0.8, 5.5),
    new THREE.MeshLambertMaterial({ color })
  );
  body.position.y = 0.7;
  body.castShadow = true;
  car.add(body);

  // Cabin
  const cabin = new THREE.Mesh(
    new THREE.BoxGeometry(2, 0.7, 2.5),
    new THREE.MeshLambertMaterial({ color: 0x88ccff })
  );
  cabin.position.set(0, 1.45, -0.3);
  cabin.castShadow = true;
  car.add(cabin);

  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.45, 0.45, 0.35, 16);
  const wheelMat = new THREE.MeshLambertMaterial({ color: 0x222222 });
  const positions = [
    [1.3, 0.45, 1.7], [-1.3, 0.45, 1.7],
    [1.3, 0.45, -1.7], [-1.3, 0.45, -1.7]
  ];
  positions.forEach(p => {
    const w = new THREE.Mesh(wheelGeo, wheelMat);
    w.rotation.z = Math.PI / 2;
    w.position.set(...p);
    car.add(w);
  });

  // Headlights
  for (const x of [-0.8, 0.8]) {
    const hl = new THREE.Mesh(
      new THREE.SphereGeometry(0.15, 8, 8),
      new THREE.MeshLambertMaterial({ color: 0xffffaa, emissive: 0xffffaa, emissiveIntensity: 0.5 })
    );
    hl.position.set(x, 0.75, 2.8);
    car.add(hl);
  }

  // Tail lights
  for (const x of [-0.8, 0.8]) {
    const tl = new THREE.Mesh(
      new THREE.BoxGeometry(0.3, 0.15, 0.05),
      new THREE.MeshLambertMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.3 })
    );
    tl.position.set(x, 0.75, -2.8);
    car.add(tl);
  }

  return car;
}

// ── Create Cars ─────────────────────────────────────────────────────
const redCar = buildCar(0xcc0000);
redCar.position.set(-3.5, 0, 0);
scene.add(redCar);

const blueCar = buildCar(0x0055ff);
blueCar.position.set(3.5, 0, 0);
scene.add(blueCar);

// ── Race Animation ──────────────────────────────────────────────────
const FRESH = 12; // seconds for a full cycle

function easeInOut(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

function animate() {
  requestAnimationFrame(animate);
  const t = (performance.now() / 1000) % FRESH;

  // Red car: starts behind, then accelerates to overtake
  const redProgress = Math.min(1, t / 6) * 1.0;
  // Blue car: steady pace, finishes first initially
  const blueProgress = Math.min(1, t / 7.5) * 0.95;

  // Actually let's make it more dramatic
  // Red car: slow start, then speeds up
  const redP = Math.min(1, t / 4) * 1.15;
  // Blue car: fast start, then maintains
  const blueP = Math.min(1, t / 5) * 1.0;

  const redZ = -redP * 250;
  const blueZ = -blueP * 250;

  redCar.position.z = redZ;
  blueCar.position.z = blueZ;

  // Camera follows the leaders
  const leadZ = Math.max(redZ, blueZ);
  const camZ = leadZ + 25;
  camera.position.set(0, 8, camZ);
  camera.lookAt(0, 2, leadZ - 20);

  renderer.render(scene, camera);
}

// Simpler, more reliable race logic
let startTime = null;
const CYCLE_DURATION = 10;

function animate() {
  requestAnimationFrame(animate);
  if (!startTime) startTime = performance.now();
  const elapsed = (performance.now() - startTime) / 1000;
  const t = (elapsed % CYCLE_DURATION) / CYCLE_DURATION; // 0..1

  // Red car: starts slow, accelerates
  // Use a sigmoid-like curve for red
  const redP = 1 / (1 + Math.exp(-20 * (t - 0.45)));
  // Blue car: fast start, then plateaus
  const blueP = 1 / (1 + Math.exp(-15 * (0.65 - t)));

  const trackLength = 250;
  const redZ = -redP * trackLength;
  const blueZ = -blueP * trackLength;

  redCar.position.z = redZ;
  blueCar.position.z = blueZ;

  // Camera follows the leader
  const leadZ = Math.max(redZ, blueZ);
  camera.position.set(0, 10, leadZ + 30);
  camera.lookAt(0, 2, leadZ - 30);

  renderer.render(scene, camera);
}

animate();

// ── Resize ──────────────────────────────────────────────────────────
window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```
